Here is the commit message:
tun: zero the whole vnet header in tun_put_user()

tun_put_user() declares an on-stack struct virtio_net_hdr_v1_hash_tunnel
without zeroing it. For a non-tunnel skb, virtio_net_hdr_tnl_from_skb()
only initializes the first 10 bytes (sizeof(struct virtio_net_hdr)),
leaving bytes 10..23 (num_buffers and the hash/tunnel fields) as stack
garbage.

An unprivileged user can set the vnet header size to 24 with
TUNSETVNETHDRSZ, so __tun_vnet_hdr_put() copies all 24 bytes of the
partially-initialized struct to userspace, leaking 14 bytes of kernel
stack on every read of a non-tunnel packet.

Fix it the same way tun_get_user() already does by zeroing the whole
header right after declaration.

Fixes: 288f30435132 ("tun: enable gso over UDP tunnel support.")
Reported-by: Weiming Shi <bestswngs@gmail.com>
Signed-off-by: Xiang Mei <xmei5@asu.edu>
Reviewed-by: Willem de Bruijn <willemb@google.com>
Link: https://patch.msgid.link/20260607054428.3050243-1-xmei5@asu.edu
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
In tun_put_user(), a local struct virtio_net_hdr_v1_hash_tunnel is declared without zeroing. For non-tunnel packets, only the virtio_net_hdr portion (first 10 bytes) is initialized, leaving bytes 10 to 23 (num_buffers and hash/tunnel fields) as uninitialized stack garbage. When userspace sets vnet header size to 24 via TUNSETVNETHDRSZ, __tun_vnet_hdr_put() copies all 24 bytes to userspace, leaking 14 bytes of kernel stack.

Here is the patch:
 /* Put packet to the user space buffer */
 static ssize_t tun_put_user(struct tun_struct *tun,
 			    struct tun_file *tfile,
 			    struct sk_buff *skb,
 			    struct iov_iter *iter)
 {
 	struct tun_pi pi = { 0, skb->protocol };
 	ssize_t total;
 	int vlan_offset = 0;
 	int vlan_hlen = 0;
 	int vnet_hdr_sz = 0;
 	int ret;

 	if (skb_vlan_tag_present(skb))
 		vlan_hlen = VLAN_HLEN;

 	if (tun->flags & IFF_VNET_HDR)
 		vnet_hdr_sz = READ_ONCE(tun->vnet_hdr_sz);

 	total = skb->len + vlan_hlen + vnet_hdr_sz;

 	if (!(tun->flags & IFF_NO_PI)) {
 		if (iov_iter_count(iter) < sizeof(pi))
 			return -EINVAL;

 		total += sizeof(pi);
 		if (iov_iter_count(iter) < total) {
 			/* Packet will be striped */
 			pi.flags |= TUN_PKT_STRIP;
 		}

 		if (copy_to_iter(&pi, sizeof(pi), iter) != sizeof(pi))
 			return -EFAULT;
 	}

 	if (vnet_hdr_sz) {
 		struct virtio_net_hdr_v1_hash_tunnel hdr;
 		struct virtio_net_hdr *gso;

+		memset(&hdr, 0, sizeof(hdr));
 		ret = tun_vnet_hdr_tnl_from_skb(tun->flags, tun->dev, skb,
 						&hdr);
 		if (ret)
 			return ret;

 		/*
 		 * Drop the packet if the configured header size is too small
 		 * WRT the enabled offloads.
 		 */
 		gso = (struct virtio_net_hdr *)&hdr;
 		ret = __tun_vnet_hdr_put(vnet_hdr_sz, tun->dev->features,
 					 iter, gso);
 		if (ret)
 			return ret;
 	}

 	if (vlan_hlen) {
 		int ret;
 		struct veth veth;

 		veth.h_vlan_proto = skb->vlan_proto;
 		veth.h_vlan_TCI = htons(skb_vlan_tag_get(skb));

 		vlan_offset = offsetof(struct vlan_ethhdr, h_vlan_proto);

 		ret = skb_copy_datagram_iter(skb, 0, iter, vlan_offset);
 		if (ret || !iov_iter_count(iter))
 			goto done;

 		ret = copy_to_iter(&veth, sizeof(veth), iter);
 		if (ret != sizeof(veth) || !iov_iter_count(iter))
 			goto done;
 	}

 	skb_copy_datagram_iter(skb, vlan_offset, iter, skb->len - vlan_offset);

 done:
 	/* caller is in process context, */
 	preempt_disable();
 	dev_sw_netstats_tx_add(tun->dev, 1, skb->len + vlan_hlen);
 	preempt_enable();

 	return total;
 }



